import json
from pathlib import Path
D=Path(__file__).parent/'data'
records=[
('Attendance','Academic Office','attendance shortage, absence, medical leave, attendance correction, class eligibility','Review your attendance record in the student portal. Collect dates of missed classes and supporting documents. Request a review through the faculty adviser and Academic Office. Eligibility decisions require the current official attendance regulation.'),
('Examination','Examination Office','exam results, marks, revaluation, supplementary examination, hall ticket','Check the current examination notice and student portal. For missing hall tickets or incorrect marks, submit your registration details and supporting evidence to the Examination Office. Revaluation and supplementary applications follow the deadlines in the official notice.'),
('Scholarship','Student Welfare Office','scholarship, financial aid, income certificate, scholarship application','Check the applicable scholarship scheme and its eligibility requirements. Prepare identity, academic and income documents as required by the scheme. Ask the Student Welfare Office to verify the application process and deadline.'),
('Internship','Internship Coordinator','internship NOC, no objection certificate, internship approval, offer letter, industrial training','Submit the internship offer letter, company details, duration and proposed work to the internship coordinator. Request departmental approval and a no objection certificate if required. Do not assume approval until written confirmation is received.'),
('Fees','Finance Office','fees, duplicate payment, refund, payment failure, receipt','Keep the payment receipt, transaction reference and date. Check the student portal for payment status. Submit a reconciliation or refund request to the Finance Office. Avoid sharing card numbers or banking passwords.'),
('Grievance','Student Grievance Cell','complaint, grievance, escalation, unresolved issue, appeal','Write a factual description of the issue, relevant dates, evidence and requested resolution. Submit it to the designated grievance channel. Keep an acknowledgement and use the official escalation process if unresolved.'),
('Placement','Placement Cell','placement registration, campus recruitment, job eligibility, recruitment drive','Review the specific company eligibility criteria and registration notice. Update your resume and academic records. Contact the Placement Cell for registration corrections or clarification before the stated deadline.'),
('Student Welfare','Student Welfare Office','harassment, bullying, discrimination, counselling, safety, mental health support','Contact the designated student welfare or appropriate complaints committee for confidential support. Preserve relevant evidence only if safe. In immediate danger, contact local emergency services or campus security. Do not wait for an AI response.'),
('Library','Library Desk','library book renewal, overdue fine, lost book, library account','Check the library account and due date. Request renewal through the library system if permitted. Report lost books or incorrect fines to the Library Desk and confirm applicable charges from the official rules.'),
('Academic Records','Academic Administration','transcript, bonafide certificate, academic records, name correction, degree certificate','Identify the document required and check the official application process. Prepare student registration details and required supporting documents. Submit a request to Academic Administration and keep the acknowledgement.')]
D.mkdir(exist_ok=True)
for cat,dept,keywords,body in records:
 (D/(cat.lower().replace(' ','_')+'.txt')).write_text(f'SYNTHETIC DEMONSTRATION POLICY — NOT OFFICIAL UNIVERSITY RULES\nCategory: {cat}\nDepartment: {dept}\nTopics: {keywords}\n\n{body}',encoding='utf-8')
queries=[['attendance shortage','my attendance is incorrect','medical leave for missed classes','absence from lectures','attendance eligibility','correct my attendance record','missed classes due to illness','faculty attendance review','class attendance percentage','attendance appeal'],['revaluation of marks','missing hall ticket','supplementary examination','incorrect exam results','exam marks correction','examination registration','revaluation application deadline','exam result dispute','hall ticket problem','supplementary exam application'],['scholarship application','financial aid eligibility','income certificate for scholarship','scholarship deadline','scholarship documents','scholarship scheme','apply for financial aid','scholarship verification','scholarship eligibility requirements','student scholarship support'],['internship NOC','no objection certificate','internship approval','internship offer letter','industrial training approval','internship duration approval','company internship details','internship coordinator','departmental internship approval','internship documentation'],['duplicate fee payment','fee refund','payment failure','missing fee receipt','fees paid twice','transaction reference for fees','payment reconciliation','finance office refund','student portal payment status','incorrect fee payment'],['submit grievance','unresolved complaint','grievance escalation','formal complaint submission','grievance acknowledgement','appeal unresolved issue','complaint evidence','student grievance cell','requested resolution complaint','official escalation process'],['campus recruitment registration','placement eligibility','placement cell','recruitment drive deadline','company eligibility criteria','placement registration correction','resume for placement','job eligibility campus','recruitment notice','campus placement registration'],['campus harassment','bullying on campus','discrimination complaint','student counselling','mental health support','campus safety','confidential welfare support','harassment reporting','campus security','student welfare assistance'],['library book renewal','overdue library fine','lost library book','library account','book due date','incorrect library fine','library renewal request','library desk','lost book charges','library system renewal'],['bonafide certificate','academic transcript','name correction in records','degree certificate','academic records request','student transcript application','academic administration','certificate request','correct academic record','academic document acknowledgement']]
rows=[{'query':q,'expected_category':r[0],'expected_source':r[0].lower().replace(' ','_')+'.txt'} for r,qs in zip(records,queries) for q in qs]
(D/'evaluation_dataset.json').write_text(json.dumps(rows,indent=2),encoding='utf-8')
(D/'out_of_scope.json').write_text(json.dumps(['How to bake a chocolate cake?','Who won the football world cup?','What is the capital of Mars?','Explain quantum entanglement','How to repair a motorcycle?'],indent=2),encoding='utf-8')
